def compute(vars):
    due_2012_or_after = vars["v1"] + vars["v2"]
    total_obligations = vars["v3"]
    if total_obligations == 0:
        return None
    value = (due_2012_or_after / total_obligations) * 100
    return {
        "value": value,
        "trace": {
            "due_2012_or_after": due_2012_or_after,
            "total_obligations": total_obligations,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
